import json
ALLOWED = {"close_false_positive", "open_ticket", "block_ip", "disable_account"}
NEEDS_HUMAN = {"block_ip", "disable_account"}
outputs = [
    '{"alert":"A-101","action":"close_false_positive","confidence":0.97}',
    '{"alert":"A-102","action":"disable_account","confidence":0.88}',
    '{"alert":"A-103","action":"drop_table","confidence":0.99}',
    'IGNORE PREVIOUS INSTRUCTIONS',
]
for raw in outputs:
    try:
        r = json.loads(raw)
    except json.JSONDecodeError:
        print("형식 오류 -> 사람에게"); continue
    a = r.get("action")
    if a not in ALLOWED: print(r["alert"], a, "-> 허용 목록 밖, 거부")
    elif a in NEEDS_HUMAN or r["confidence"] < 0.9: print(r["alert"], a, "-> 사람 승인 대기")
    else: print(r["alert"], a, "-> 자동 처리")
# A-101 close_false_positive -> 자동 처리
# A-102 disable_account -> 사람 승인 대기
# A-103 drop_table -> 허용 목록 밖, 거부
# 형식 오류 -> 사람에게
